//! The blackjack table on angzarr-embedded, angzarr's in-app runtime: the
//! table aggregate and the two policies between it and the player bot,
//! written in angzarr-embedded's markup (`#[aggregate]`, `#[policy]`) as
//! THIN ADAPTERS. The logic is plain Rust behind traits with no harness in
//! it: agg-table's `TableLogic` and table-player-policies' `TablePlayer` and
//! `PlayerTable`. The adapters were generated by `angzarr scaffold rust` and
//! each hand edit is marked `HAND-EDIT`, so they can be regenerated as the
//! scaffold changes.
//!
//! - [`domain`]: each command, event and refusal object as the domain type
//!   the markup takes (hand-written: the generator refuses table.proto);
//! - [`TableRefused`]: agg-table's rejection as the domain's
//!   untyped rejection, a localizable diagnostic (its code and args);
//! - [`TableAggregate`]: the table;
//! - [`TablePlayerPolicy`] and [`PlayerTablePolicy`]: TurnStarted to the
//!   player bot's DecideMove, and its MoveDecided back to Hit, Stand or
//!   DoubleDown;
//! - [`PlayerAggregate`]: the player bot's contract, for the policies to
//!   type-check against; never registered. The bot itself is Python, run
//!   as a child process by angzarr-embedded-host (`tests/remote_player.rs`
//!   plays a hand with it).
//!
//! Register the table with
//! `registry.aggregate::<TableAggregate>(TableAggregate::default)` and the
//! policies with `registry.policy(..)`, beside the remote player
//! (`angzarr_embedded_host::run(config, register)`).

pub mod domain;
// The scaffold's stubs name parameters they do not use until written.
#[allow(unused_variables)]
mod player_aggregate;
mod player_table_policy;
mod refused;
mod table_aggregate;
mod table_player_policy;

pub use player_aggregate::PlayerAggregate;
pub use player_table_policy::PlayerTablePolicy;
pub use refused::TableRefused;
pub use table_aggregate::TableAggregate;
pub use table_player_policy::TablePlayerPolicy;
